#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/docker.restate.dev-restatedev-restate-1.8.1-hotfix.2-arm64-oci ] || "$F" docker.restate.dev/restatedev/restate sha256:727dc7f0e91baebe9059f636522deb531cd0bdce669e744b2d7cc6c9850f6660 docker.restate.dev/restatedev/restate:1.8.1-hotfix.2 images/docker.restate.dev-restatedev-restate-1.8.1-hotfix.2-arm64-oci
[ "$A" = arm64 ] || [ -f images/docker.restate.dev-restatedev-restate-1.8.1-hotfix.2-amd64.docker.tar ] || "$F" docker.restate.dev/restatedev/restate sha256:e239ab0c89cc6417705045ce7d2fee9ef49e0456c55157fa298e29e724f6fb58 docker.restate.dev/restatedev/restate:1.8.1-hotfix.2 images/docker.restate.dev-restatedev-restate-1.8.1-hotfix.2-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/docker.restate.dev-restatedev-restate-1.8.1-hotfix.2-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/docker.restate.dev-restatedev-restate-1.8.1-hotfix.2-arm64-oci
